import pulp

# Data
containers = [1, 2, 3, 4, 5, 6]
capacities = {1: 1500, 2: 2500, 3: 4000, 4: 6000, 5: 9000, 6: 12000}
demands = {1: 500, 2: 550, 3: 700, 4: 900, 5: 400, 6: 300}
variable_costs = {1: 5, 2: 8, 3: 10, 4: 12, 5: 16, 6: 18}
fixed_cost = 1200

# Decision variables
# x[i][j]: number of containers of type j produced to satisfy demand of type i
# i is the demand type, j is the production type
# Constraint: j must have capacity >= capacity of i
x = {}
for i in containers:
    for j in containers:
        if capacities[j] >= capacities[i]:
            x[i, j] = pulp.LpVariable(f"x_{i}_{j}", lowBound=0, cat='Integer')

# y[j]: binary variable indicating if type j is produced
y = {j: pulp.LpVariable(f"y_{j}", cat='Binary') for j in containers}

# Objective: minimize total cost
prob = pulp.LpProblem("Container_Production", pulp.LpMinimize)
prob += (
    pulp.lpSum(
        variable_costs[j] * x[i, j]
        for i in containers
        for j in containers
        if (i, j) in x
    )
    + fixed_cost * pulp.lpSum(y[j] for j in containers)
)

# Constraints
# 1. Demand satisfaction: for each demand type i, sum of production from eligible types j must meet demand
for i in containers:
    prob += (
        pulp.lpSum(x[i, j] for j in containers if (i, j) in x) >= demands[i],
        f"Demand_{i}"
    )

# 2. Linking constraints: if any x[i,j] > 0, then y[j] must be 1
# We use: x[i,j] <= M * y[j] where M is an upper bound on x[i,j]
# A safe upper bound for x[i,j] is the total demand of type i (since it can't exceed demand[i] in practice, but to be safe, use sum of all demands or just demand[i])
# Actually, x[i,j] cannot exceed demand[i] because we only need to satisfy demand[i]. So M = demand[i] is sufficient.
for i in containers:
    for j in containers:
        if (i, j) in x:
            prob += x[i, j] <= demands[i] * y[j], f"Link_{i}_{j}"

# Solve
prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))

# Output
print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")
