import pulp

# Define the problem
prob = pulp.LpProblem("Production_Planning", pulp.LpMinimize)

# Data
products = ['I', 'II', 'III']
quarters = [1, 2, 3, 4]

# Contract orders
orders = {
    'I': {1: 1500, 2: 1000, 3: 2000, 4: 1200},
    'II': {1: 1500, 2: 1500, 3: 1200, 4: 1500},
    'III': {1: 1000, 2: 2000, 3: 1500, 4: 2500}
}

# Production time per unit
prod_time = {'I': 2, 'II': 4, 'III': 3}

# Production capacity per quarter
capacity = 15000

# Compensation per unit per quarter for late delivery
compensation = {'I': 20, 'II': 20, 'III': 10}

# Storage fee per unit per quarter
storage_fee = 5

# End-of-quarter 4 inventory requirement
end_inventory_req = 150

# Decision variables
# x[p][q] = units of product p produced in quarter q
x = {}
for p in products:
    for q in quarters:
        x[p][q] = pulp.LpVariable(f"x_{p}_{q}", lowBound=0)

# s[p][q] = units of product p in inventory at end of quarter q
s = {}
for p in products:
    for q in quarters:
        s[p][q] = pulp.LpVariable(f"s_{p}_{q}", lowBound=0)

# l[p][q] = units of product p delivered late (shortage) in quarter q
l = {}
for p in products:
    for q in quarters:
        l[p][q] = pulp.LpVariable(f"l_{p}_{q}", lowBound=0)

# Objective function: minimize total compensation and storage fees
prob += (
    pulp.lpSum(
        compensation[p] * l[p][q] + storage_fee * s[p][q]
        for p in products
        for q in quarters
    )
)

# Constraints

# Production capacity constraint for each quarter
for q in quarters:
    prob += (
        pulp.lpSum(prod_time[p] * x[p][q] for p in products) <= capacity,
        f"Capacity_Q{q}"
    )

# Product I cannot be produced in quarter 2
prob += x['I'][2] == 0, "No_Production_I_Q2"

# Inventory balance constraints
# For each product and quarter:
# s[p][q] = s[p][q-1] + x[p][q] - orders[p][q] + l[p][q]
# where s[p][0] = 0 (no initial inventory)
for p in products:
    for q in quarters:
        if q == 1:
            prob += (
                s[p][q] == x[p][q] - orders[p][q] + l[p][q],
                f"Balance_{p}_Q{q}"
            )
        else:
            prob += (
                s[p][q] == s[p][q-1] + x[p][q] - orders[p][q] + l[p][q],
                f"Balance_{p}_Q{q}"
            )

# End of quarter 4 inventory requirement
for p in products:
    prob += s[p][4] >= end_inventory_req, f"End_Inventory_{p}"

# Solve the problem
prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))

# Print the result
print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")
